def _normalize(value):
    return "".join(
        character for character in (value or "").casefold() if character.isalnum()
    )


def resolve_language(text, languages):
    """The first Language named by any part of text, as staff matched requests."""
    requested = {_normalize(part) for part in re.split(r"[/,;()]+", text or "")}
    requested.discard("")
    return next(
        (
            language
            for language in languages
            if requested & {_normalize(language.language), _normalize(language.bcp47)}
        ),
        None,
    )


def match_requested_languages(apps, schema_editor):
    Language = apps.get_model("core", "Language")
    ResourceIntakeRequest = apps.get_model("core", "ResourceIntakeRequest")
    languages = list(Language.objects.order_by("language"))
    for intake_request in ResourceIntakeRequest.objects.all():
        intake_request.audio_language_match = resolve_language(
            intake_request.audio_language, languages
        )
        intake_request.subtitle_language_match = resolve_language(
            intake_request.subtitle_language, languages
        )
        intake_request.save(
            update_fields=["audio_language_match", "subtitle_language_match"]
        )


def pin_pause_end_times(apps, schema_editor):
    PauseAnnotation = apps.get_model("core", "PauseAnnotation")
    PauseAnnotation.objects.update(end_time=models.F("start_time"))


